package com.ai.assistance.operit.api.chat.error

internal enum class RequestFailureDomain { TRANSPORT, CLIENT, PROTOCOL, PROVIDER, UNCLASSIFIED }

/** 编号仅对应一个可观察条件，不把观测异常当成连接责任归因。 */
internal enum class RequestFailureCode(
    val code: Int,
    val type: String,
    val explanation: String,
    val domain: RequestFailureDomain,
    val retryable: Boolean,
) {
    HOST_RESOLUTION_FAILED(5000, "host_resolution_failed", "The system could not resolve the API host.", RequestFailureDomain.TRANSPORT, true),
    CONNECTION_ABORTED(5003, "connection_aborted", "The socket reported ECONNABORTED; its initiator is undetermined.", RequestFailureDomain.TRANSPORT, true),
    FIRST_TOKEN_TIMEOUT(5004, "first_token_timeout", "The client cancelled the request after ten minutes without a recognized first output.", RequestFailureDomain.CLIENT, true),
    CONNECT_TIMEOUT(5010, "connect_timeout", "Opening the socket timed out.", RequestFailureDomain.TRANSPORT, true),
    REQUEST_HEADERS_WRITE_TIMEOUT(5011, "request_headers_write_timeout", "Writing the request headers timed out.", RequestFailureDomain.TRANSPORT, true),
    RESPONSE_HEADERS_TIMEOUT(5012, "response_headers_timeout", "Waiting for response headers timed out.", RequestFailureDomain.TRANSPORT, true),
    RESPONSE_READ_TIMEOUT(5013, "response_read_timeout", "Reading the response body timed out.", RequestFailureDomain.TRANSPORT, true),
    SOCKET_TIMEOUT_UNLOCATED(5014, "socket_timeout_unlocated", "SocketTimeoutException occurred without an observed request phase.", RequestFailureDomain.TRANSPORT, true),
    TLS_TIMEOUT(5015, "tls_timeout", "Negotiating TLS timed out.", RequestFailureDomain.TRANSPORT, true),
    REQUEST_BODY_WRITE_TIMEOUT(5016, "request_body_write_timeout", "Writing the request body timed out.", RequestFailureDomain.TRANSPORT, true),
    DNS_TIMEOUT(5017, "dns_timeout", "Resolving the API host raised SocketTimeoutException.", RequestFailureDomain.TRANSPORT, true),
    CONNECTION_REFUSED(5020, "connection_refused", "The socket reported ECONNREFUSED.", RequestFailureDomain.TRANSPORT, true),
    HOST_UNREACHABLE(5021, "host_unreachable", "The system reported an unreachable host.", RequestFailureDomain.TRANSPORT, true),
    NETWORK_UNREACHABLE(5022, "network_unreachable", "The socket reported ENETUNREACH.", RequestFailureDomain.TRANSPORT, true),
    PORT_UNREACHABLE(5023, "port_unreachable", "The system reported PortUnreachableException.", RequestFailureDomain.TRANSPORT, true),
    CONNECTION_RESET(5030, "connection_reset", "The socket reported ECONNRESET; its initiator is undetermined.", RequestFailureDomain.TRANSPORT, true),
    SOCKET_CLOSED(5031, "socket_closed", "The socket was closed; its initiator is undetermined.", RequestFailureDomain.TRANSPORT, true),
    BROKEN_PIPE(5032, "broken_pipe", "Writing to the socket reported EPIPE.", RequestFailureDomain.TRANSPORT, true),
    SOCKET_NOT_CONNECTED(5033, "socket_not_connected", "The socket reported ENOTCONN.", RequestFailureDomain.TRANSPORT, true),
    TLS_PEER_UNVERIFIED(5040, "tls_peer_unverified", "The TLS peer identity could not be verified.", RequestFailureDomain.TRANSPORT, false),
    CERTIFICATE_EXPIRED(5041, "certificate_expired", "A certificate has expired.", RequestFailureDomain.TRANSPORT, false),
    CERTIFICATE_NOT_YET_VALID(5042, "certificate_not_yet_valid", "A certificate is not yet valid.", RequestFailureDomain.TRANSPORT, false),
    CERTIFICATE_PATH_INVALID(5043, "certificate_path_invalid", "The certificate path could not be validated.", RequestFailureDomain.TRANSPORT, false),
    CERTIFICATE_INVALID(5044, "certificate_invalid", "Certificate processing raised CertificateException.", RequestFailureDomain.TRANSPORT, false),
    TLS_HANDSHAKE_FAILED(5045, "tls_handshake_failed", "TLS negotiation raised SSLHandshakeException.", RequestFailureDomain.TRANSPORT, false),
    TLS_PROTOCOL_ERROR(5046, "tls_protocol_error", "TLS processing raised SSLProtocolException.", RequestFailureDomain.TRANSPORT, false),
    HTTP2_CANCEL(5050, "http2_cancel", "An HTTP/2 stream reported CANCEL; its initiator is undetermined.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_REFUSED_STREAM(5051, "http2_refused_stream", "The HTTP/2 stream reported REFUSED_STREAM.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_PROTOCOL_ERROR(5052, "http2_protocol_error", "The HTTP/2 stream reported PROTOCOL_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_INTERNAL_ERROR(5053, "http2_internal_error", "The HTTP/2 stream reported INTERNAL_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_FLOW_CONTROL_ERROR(5054, "http2_flow_control_error", "The HTTP/2 stream reported FLOW_CONTROL_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_ENHANCE_YOUR_CALM(5055, "http2_enhance_your_calm", "The HTTP/2 stream reported ENHANCE_YOUR_CALM.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_INADEQUATE_SECURITY(5056, "http2_inadequate_security", "The HTTP/2 stream reported INADEQUATE_SECURITY.", RequestFailureDomain.TRANSPORT, false),
    HTTP2_HTTP_1_1_REQUIRED(5057, "http2_http_1_1_required", "The HTTP/2 stream reported HTTP_1_1_REQUIRED.", RequestFailureDomain.TRANSPORT, false),
    HTTP2_STREAM_CLOSED(5058, "http2_stream_closed", "The HTTP/2 stream reported STREAM_CLOSED.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_CONNECT_ERROR(5059, "http2_connect_error", "The HTTP/2 stream reported CONNECT_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_SETTINGS_TIMEOUT(5060, "http2_settings_timeout", "The HTTP/2 stream reported SETTINGS_TIMEOUT.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_COMPRESSION_ERROR(5061, "http2_compression_error", "The HTTP/2 stream reported COMPRESSION_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_NO_ERROR_RESET(5062, "http2_no_error_reset", "The HTTP/2 stream reported a NO_ERROR reset.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_CONNECTION_SHUTDOWN(5063, "http2_connection_shutdown", "OkHttp reported HTTP/2 ConnectionShutdownException.", RequestFailureDomain.TRANSPORT, true),
    HTTP2_FRAME_SIZE_ERROR(5064, "http2_frame_size_error", "The HTTP/2 stream reported FRAME_SIZE_ERROR.", RequestFailureDomain.TRANSPORT, true),
    HTTP_PROTOCOL_ERROR(5070, "http_protocol_error", "The HTTP exchange raised ProtocolException.", RequestFailureDomain.PROTOCOL, false),
    RESPONSE_HEADERS_EOF(5071, "response_headers_eof", "The response headers ended unexpectedly.", RequestFailureDomain.TRANSPORT, true),
    RESPONSE_BODY_EOF(5072, "response_body_eof", "The response body ended unexpectedly.", RequestFailureDomain.TRANSPORT, true),
    STREAM_JSON_INVALID(5080, "stream_json_invalid", "A data event is not valid JSON.", RequestFailureDomain.PROTOCOL, false),
    RESPONSE_JSON_INVALID(5081, "response_json_invalid", "The response body is not valid JSON.", RequestFailureDomain.PROTOCOL, false),
    RESPONSE_BODY_MISSING(5082, "response_body_missing", "A successful HTTP response has no response body.", RequestFailureDomain.PROTOCOL, true),
    STREAM_COMPLETION_MISSING(5083, "stream_completion_missing", "The response ended without the required completion event.", RequestFailureDomain.PROTOCOL, true),
    RESPONSE_SHAPE_INVALID(5084, "response_shape_invalid", "The decoded response lacks required fields.", RequestFailureDomain.PROTOCOL, false);
}
